        var frameOffset = 0;
        var generation = Volatile.Read(ref session.FrameGeneration);
        var processCheck = Stopwatch.StartNew();

        while (!token.IsCancellationRequested)
        {
            if (WaitHandle.WaitAny(waits, 250) == 0) break;
            if (processCheck.ElapsedMilliseconds >= 1000)
