                var nextGeneration = Volatile.Read(ref session.FrameGeneration);
                if (nextGeneration != generation ||
                    (flags & AudioClientBufferFlags.DataDiscontinuity) != 0)
                {
                    frameOffset = 0;
                    vad.ResetState();
                    generation = nextGeneration;
