                    if (token.IsCancellationRequested || session.Paused ||
                        generation != Volatile.Read(ref session.FrameGeneration))
                        break;

                    frame[frameOffset++] = pcm[i] / 32768f;
                    if (frameOffset != frame.Length) continue;
                    
                    var firstSpeech = vad.SpeechDetection(frame.AsSpan(0, VadFrameSamples));
                    var secondSpeech = vad.SpeechDetection(frame.AsSpan(VadFrameSamples, VadFrameSamples));
                    frameOffset = 0;
                    if (!token.IsCancellationRequested && !session.Paused &&
                        generation == Volatile.Read(ref session.FrameGeneration))
                    {
                        try
                        {
                            OnDataReceived?.Invoke(frame, firstSpeech || secondSpeech);
                        }
                        catch (Exception e)
                        {
                            Log.Error(e, "[LOOP] Audio subscriber failed");
                        }
                    }
                    
                    frame = new float[OutputFrameSamples];
                }
            }
        }
